function updateC26Finishers(dt){for(let i=c26Finishers.length-1;i>=0;i--){const f=c26Finishers[i];f.age+=dt;f.art.update(f.age);if(f.age>=f.art.duration){f.art.model.removeFromParent();f.art.dispose();c26Finishers.splice(i,1);if(!c26Finishers.length)c26Audio.stop('finisher');}}}
