 $('naruForm').onchange=e=>{prefs.naruForm=e.target.value;naruMotion.cancel();naruMotion.form=prefs.naruForm;save();selectedPreview='knife';buildWeapon('knife',true);$('naruSeek').classList.add('hidden');};
 let request=0;
 const play=async speed=>{const id=++request,active=naruPreview;unlockAudio();active.playing=false;naruAudio.stop();championAudio.stop();if(speed===1)await naruAudio.preload(audioCtx);if(request!==id||naruPreview!==active||currentTab!=='collection')return;if(active.frame>=NARU_CLIPS[active.clip].frames)active.frame=0;active.speed=speed;active.anchorFrame=active.frame;active.clock=performance.now();active.playing=true;if(speed===1)naruAudio.play(audioCtx,active.clip,prefs.volume*.8,active.frame/60);};
 const start=kind=>{const form=prefs.naruForm||'long';selectedPreview='knife';buildWeapon('knife',false);naruPreview.form=form;naruPreview.clip=kind==='draw'?(form==='long'?'drawLong':'drawKunai'):(form==='long'?'toKunai':'toLong');document.body.classList.add('equip-preview');$('naruSeek').classList.remove('hidden');$('naruFrame').max=NARU_CLIPS[naruPreview.clip].frames;play(1);};
 $('naruDraw').onclick=()=>start('draw');$('naruTransform').onclick=()=>start('transform');
