 $('naruFrame').oninput=e=>seek(Number(e.target.value));$('naruPrev').onclick=()=>seek(Math.ceil(naruPreview.frame)-1);$('naruNext').onclick=()=>seek(Math.floor(naruPreview.frame)+1);
