 weaponGroup.position.set(0,naruPreview.clip ? 0 : -.05,naruPreview.clip?-1.35:-1.65);weaponGroup.rotation.set(0,0,0);weaponGroup.scale.setScalar(portrait ? .52 : naruPreview.clip ? .87 : .66);
 if(naruPreview.clip){const n=NARU_CLIPS[naruPreview.clip].frames;if(naruPreview.playing)naruPreview.frame=Math.min(n,naruPreview.anchorFrame+(performance.now()-naruPreview.clock)/1000*60*naruPreview.speed);if(naruPreview.frame>=n)naruPreview.playing=false;const opts={form:naruPreview.form,clip:naruPreview.clip,seconds:naruPreview.frame/60,time:naruPreview.frame/60};weaponArt.update(opts);$('naruFrame').value=naruPreview.frame;$('naruFrameLabel').textContent=Math.floor(naruPreview.frame)+' / '+n+' 帧';$('naruStage').textContent=sampleNaru(opts).stage;$('naruPlay').textContent=naruPreview.playing?'暂停泷吟动作':'原速播放泷吟';}
 else weaponArt.update({form:prefs.naruForm,time:elapsed});
