 $('chaosPlay').onclick=()=>{if(chaosPreview.frame>=72)chaosPreview.frame=0;chaosPreview.playing=!chaosPreview.playing};
 $('chaosDrawSound').onclick=async()=>{unlockAudio();await chaosAudio.preload(audioCtx);chaosAudio.play(audioCtx,'equip',prefs.volume*.8)};
