 const previewChaosKill=async(head=false)=>{unlockAudio();const count=Number($('chaosKillLevel').value),activePreview=chaosPreview,request=++chaosKillRequestId;$('chaosAudioStatus').textContent='正在加载音效…';chaosAudio.stop('kill');await chaosAudio.preload(audioCtx);if(chaosPreview!==activePreview||request!==chaosKillRequestId||currentTab!=='collection'||!$('chaosAudioStatus'))return;chaosPreview.killAt=elapsed;chaosPreview.killFrame=0;chaosPreview.killPlaying=true;chaosPreview.killSpeed=1;if(head)combatAudio.headshot(audioCtx,prefs.volume);const ok=chaosAudio.play(audioCtx,'kill'+count,prefs.volume*.9);$('chaosAudioStatus').textContent=ok?'第 '+count+' 杀 · 独立音频':'音效暂未加载，请重新点按试听';};
