 const playReloadSound=()=>{chaosPreview.reloadClock=performance.now();chaosPreview.reloadStartFrame=chaosPreview.reloadFrame;if(chaosPreview.reloadSpeed===1)chaosAudio.play(audioCtx,'reload',prefs.volume*.8,chaosPreview.reloadFrame/60)};
 $('chaosReload').onclick=async()=>{prepareReload();const activePreview=chaosPreview,request=++reloadRequestId;unlockAudio();await chaosAudio.preload(audioCtx);if(chaosPreview!==activePreview||currentTab!=='collection'||request!==reloadRequestId)return;chaosPreview.reloadPlaying=true;playReloadSound()};
