 $('chaosBadgeFrame').oninput=e=>{chaosKillRequestId++;chaosAudio.stop('kill');chaosPreview.killPlaying=false;chaosPreview.killFrame=Number(e.target.value)};
 $('chaosBadgePrev').onclick=()=>{chaosKillRequestId++;chaosAudio.stop('kill');chaosPreview.killPlaying=false;chaosPreview.killFrame=Math.max(0,Math.ceil(chaosPreview.killFrame)-1)};
 $('chaosBadgeNext').onclick=()=>{chaosKillRequestId++;chaosAudio.stop('kill');chaosPreview.killPlaying=false;chaosPreview.killFrame=Math.min(144,Math.floor(chaosPreview.killFrame)+1)};
 $('chaosBadgeSlow').onclick=()=>{chaosKillRequestId++;chaosAudio.stop('kill');chaosPreview.killAt=elapsed;chaosPreview.killFrame=0;chaosPreview.killPlaying=true;chaosPreview.killSpeed=.25;};
 updateChaosBadge($('chaosBadgePreview'),.9);
