function updateChaosPreview(dt,portrait){
 if(!chaosPreview.equip&&!chaosPreview.inspect&&!chaosPreview.reload)weaponGroup.rotation.set(.30,.95,-.22);
 if(chaosPreview.equip||chaosPreview.inspect||chaosPreview.reload){weaponGroup.position.set(.29,-.26,-.69);weaponGroup.rotation.set(0,0,0);weaponGroup.scale.setScalar(portrait?.50:.78)}
 if(chaosPreview.equip){if(chaosPreview.playing)chaosPreview.frame=Math.min(CHAOS_FRAMES,chaosPreview.frame+dt*CHAOS_FPS*.25);if(chaosPreview.frame>=CHAOS_FRAMES)chaosPreview.playing=false;weaponArt.update({time:chaosPreview.frame/60,equipSeconds:chaosPreview.frame/60});$('chaosFrame').value=chaosPreview.frame;$('chaosFrameLabel').textContent=Math.floor(chaosPreview.frame)+' / 72 帧';$('chaosPlay').textContent=chaosPreview.playing?'暂停慢放':'¼ 倍慢放';}
 else if(chaosPreview.reload){if(chaosPreview.reloadPlaying)chaosPreview.reloadFrame=Math.min(CHAOS_RELOAD_FRAMES,chaosPreview.reloadStartFrame+(performance.now()-chaosPreview.reloadClock)/1000*CHAOS_RELOAD_FPS*chaosPreview.reloadSpeed);if(chaosPreview.reloadFrame>=CHAOS_RELOAD_FRAMES)chaosPreview.reloadPlaying=false;const seconds=chaosPreview.reloadFrame/60;weaponArt.update({time:seconds,reloadSeconds:seconds});$('chaosReloadFrame').value=chaosPreview.reloadFrame;$('chaosReloadLabel').textContent=Math.floor(chaosPreview.reloadFrame)+' / 156 帧';$('chaosReloadStage').textContent=sampleChaosReload(seconds).stage;$('chaosReloadPlay').textContent=chaosPreview.reloadPlaying?'暂停换弹':'原速播放换弹';}
 else weaponArt.update({time:elapsed,inspect:chaosPreview.inspect?(elapsed%2.6)/2.6:0});
 if($('chaosBadgePreview')){if(chaosPreview.killPlaying){chaosPreview.killFrame=Math.min(144,(elapsed-chaosPreview.killAt)*60*chaosPreview.killSpeed);if(chaosPreview.killFrame>=144)chaosPreview.killPlaying=false;}const pose=updateChaosBadge($('chaosBadgePreview'),chaosPreview.killFrame/60);$('chaosBadgeFrame').value=Math.floor(chaosPreview.killFrame);$('chaosBadgeFrameLabel').textContent=Math.floor(chaosPreview.killFrame)+' / 144 帧 · '+pose.phase;}
}
