 const seek=f=>{championRequest++;championAudio.stop();if(!championPreview.active)start();championPreview.frame=clamp(f,0,47);championPreview.playing=false;};$('championFrame').oninput=e=>seek(+e.target.value);$('championPrev').onclick=()=>seek(Math.ceil(championPreview.frame)-1);$('championNext').onclick=()=>seek(Math.floor(championPreview.frame)+1);$('championSlow').onclick=()=>{if(!championPreview.active)start();play(.25)};$('championPause').onclick=()=>{if(championPreview.playing){championPreview.playing=false;championAudio.stop()}else play(championPreview.speed)};$('championInspect').onclick=()=>{start();championPreview.inspect=true;championPreview.clock=performance.now();$('championSeek').classList.add('hidden');};
