function updateChampionPreview(portrait){weaponGroup.position.set(0,championPreview.active?.19:0,championPreview.active?-1.35:-2.25);weaponGroup.rotation.set(0,0,0);weaponGroup.scale.setScalar(portrait?.43:championPreview.active?.66:1);if(championPreview.playing)championPreview.frame=Math.min(47,championPreview.anchor+(performance.now()-championPreview.clock)*.06*championPreview.speed);if(championPreview.frame>=47)championPreview.playing=false;weaponArt.update({time:elapsed,equipSeconds:championPreview.active&&!championPreview.inspect?championPreview.frame/60:null,inspect:championPreview.inspect,inspectSeconds:((performance.now()-championPreview.clock)/1000)%2.6,topFrag:true});if($('championFrame')){$('championFrame').value=championPreview.frame;$('championLabel').textContent=Math.floor(championPreview.frame)+' / 47 帧 · '+sampleChampion(championPreview.frame/60).phase;}}
