 $('knifeList').insertAdjacentHTML('beforeend',`<div class="kuronami-options mercy-options"><label for="mercyVariant">怜悯之刃配色</label><select id="mercyVariant">${Object.entries(MERCY_VARIANTS).map(([id,c])=>`<option value="${id}">${c.name}</option>`).join('')}</select><button id="mercyEquip" class="secondary">预览怜悯切刀</button><div id="mercySeek" class="hidden"><label for="mercyFrame">切刀慢放 · <output id="mercyFrameLabel">0 / 48 帧</output></label><input id="mercyFrame" aria-label="怜悯切刀动画帧" type="range" min="0" max="48" step="1" value="0"><div class="mercy-step-row"><button id="mercyPrev" class="secondary">上一帧</button><button id="mercyNext" class="secondary">下一帧</button></div><button id="mercyPlay" class="secondary">¼ 倍慢放</button></div><button id="mercyInspect" class="secondary">预览怜悯检视</button><p>VCT LOCK//IN · 四种配色<br>翻腕接刀 · 弧形刀光<br>击杀数领先时激活发光效果</p></div>`);
 $('mercyVariant').value=prefs.mercyVariant||'red';$('mercyVariant').onchange=e=>{prefs.mercyVariant=e.target.value;selectedPreview='knife';save();buildWeapon('knife',true);renderCollection()};
