 $('mercyPlay').onclick=()=>{if(mercyPreview.frame>=48)mercyPreview.frame=0;mercyPreview.playing=!mercyPreview.playing};$('mercyInspect').onclick=()=>{selectedPreview='knife';buildWeapon('knife',false);mercyPreview.inspect=true;document.body.classList.add('equip-preview');$('mercySeek').classList.add('hidden')};
