function shopState(){return{money,primary,sidearm,armor:player.armor,armorType:player.armorType,armorPool:player.armorPool,armorHitAt:player.armorHitAt};}
function tradeItem(id,refund=false){if(state!=='playing'||!player.alive||overlayType!=='buy'||(mode==='team'?phase!=='live':phase!=='buy'))return false;const result=shopAction(shopState(),shopLedger,id,{phase,team:mode==='team',refund});if(!result.ok){notify(result.reason);return false;}const gunChanged=primary!==result.state.primary,pistolChanged=sidearm!==result.state.sidearm;money=result.state.money;primary=result.state.primary;sidearm=result.state.sidearm||'classic';for(const key of ['armor','armorType','armorPool','armorHitAt'])player[key]=result.state[key];shopLedger=result.ledger;if(gunChanged||pistolChanged){cancelScopeHold();cancelCast();currentSlot=pistolChanged?1:primary==='classic'?1:0;lastGunSlot=currentSlot;const id=weaponId();inventory[id]={ammo:WEAPONS[id].mag,reserve:WEAPONS[id].reserve};reloadLeft=0;buildWeapon();switchTime=drawDuration();}tone(660,.09,'sine',.1);updateHUD();renderOverlay('buy');return true;}
function renderShop(b){b.innerHTML=shopMarkup({team:mode==='team',phase,...shopState(),ledger:shopLedger,agent:getAgent(player.agent),kit:player.kit,teammates:entities.filter(e=>e.team===player.team).map(e=>({name:e.name,icon:getAgent(e.agent).icon,alive:e.alive})),round});for(const btn of b.querySelectorAll('[data-buy]'))btn.onclick=()=>tradeItem(btn.dataset.buy);for(const btn of b.querySelectorAll('[data-refund]'))btn.onclick=()=>tradeItem(btn.dataset.refund,true);$('buyDone').onclick=closeOverlay;$('skipBuy').onclick=()=>{if(phase==='buy')beginLive();closeOverlay()};}
function getSpectated(step=0){const target=spectatorTarget(entities,player.team,spectatedId,step);spectatedId=target?.seed??-1;return target;}
function cycleSpectator(step){if(state==='playing'&&!player.alive&&!paused){getSpectated(step);updatePlayer(0);updateHUD();}}
function applyQuality(){renderer.setPixelRatio(prefs.quality==='performance'?1:Math.min(devicePixelRatio,prefs.quality==='high'?2:touchDevice?1.4:1.75));renderer.shadowMap.enabled=prefs.quality==='high'||(prefs.quality==='balanced'&&!touchDevice);renderer.setSize(innerWidth,innerHeight)}
